SELECT r."report_id", r."version_no", r."resource_id", r."namespace", r."resource_path", r."content", r."content_size", r."content_sha256", r."created_at", r."media_type", r."is_binary" FROM (SELECT resource_file."report_id", resource_file."version_no", resource_file."resource_id", resource_file."namespace", resource_file."resource_path", resource_file."media_type", resource_file."content", resource_file."content_size", resource_file."content_sha256", resource_file."is_binary", resource_file."created_at", resource_file."should_delete" FROM  (SELECT f.*, '' AS should_delete FROM report_resource_files f
)  resource_file WHERE 1 = 1) r WHERE $criteria.CompositeIn("r", $FileKeys)